  "ei.a.lt5": "2017-18 ਤੋਂ ਕਿਸੇ ਵੀ ਸਾਲ ₹5 ਕਰੋੜ ਤੋਂ ਉੱਪਰ ਨਹੀਂ",
  "ei.a.5to10": "ਕਿਸੇ ਸਾਲ ₹5 ਕਰੋੜ ਤੋਂ ਉੱਪਰ, ਪਿਛਲੇ ਸਾਲ ₹10 ਕਰੋੜ ਤੋਂ ਘੱਟ",
