  "ei.h.aato": "ਇਸ ਨਾਲ ਤੈਅ ਹੁੰਦਾ ਹੈ ਕਿ ਈ-ਇਨਵੌਇਸ ਤੁਹਾਡੇ ’ਤੇ ਲਾਗੂ ਹੈ ਜਾਂ ਨਹੀਂ, ਅਤੇ 30 ਦਿਨਾਂ ਦੀ ਹੱਦ ਲਾਗੂ ਹੈ ਜਾਂ ਨਹੀਂ। ਇਹ ਇਸੇ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਯਾਦ ਰਹਿੰਦਾ ਹੈ।",
  "ev.hsn6": "ਆਈਟਮ {n}: ਈ-ਇਨਵੌਇਸ ਵਿੱਚ 6 ਜਾਂ 8 ਅੰਕਾਂ ਦਾ HSN/SAC ਕੋਡ ਚਾਹੀਦਾ ਹੈ (4 ਅੰਕ ਸਿਰਫ਼ ₹5 ਕਰੋੜ ਤੋਂ ਘੱਟ ਵਾਲੇ ਬਿਜ਼ਨੈੱਸ ਲਈ ਹਨ, ਜੋ ਈ-ਇਨਵੌਇਸ ਨਹੀਂ ਬਣਾਉਂਦੇ)।",
  "ev.old30": "ਇਹ ਇਨਵੌਇਸ 30 ਜਾਂ ਵੱਧ ਦਿਨ ਪੁਰਾਣਾ ਹੈ। ₹10 ਕਰੋੜ ਜਾਂ ਵੱਧ ਟਰਨਓਵਰ ’ਤੇ ਪੋਰਟਲ ਇਸਨੂੰ ਹੁਣ ਰਜਿਸਟਰ ਨਹੀਂ ਕਰਦਾ। ਨਵਾਂ ਇਨਵੌਇਸ ਬਣਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਆਪਣੇ ਅਕਾਊਂਟੈਂਟ ਨੂੰ ਪੁੱਛੋ।",
  "ev.lt5": "ਈ-ਇਨਵੌਇਸ ਤੁਹਾਡੇ ਲਈ ਜ਼ਰੂਰੀ ਨਹੀਂ, ਜਦੋਂ ਤੱਕ 2017-18 ਤੋਂ ਕਿਸੇ ਸਾਲ ਤੁਹਾਡਾ ਟਰਨਓਵਰ ₹5 ਕਰੋੜ ਪਾਰ ਨਾ ਹੋਇਆ ਹੋਵੇ।",
  "ev.old180": "180 ਦਿਨਾਂ ਤੋਂ ਪੁਰਾਣੇ ਡਾਕੂਮੈਂਟ ਦਾ ਈ-ਵੇ ਬਿੱਲ ਪੋਰਟਲ ਨਹੀਂ ਬਣਾਉਂਦਾ।",
  "ev.smallst": "{st} ਦੇ ਅੰਦਰ ਈ-ਵੇ ਬਿੱਲ ਆਮ ਤੌਰ ’ਤੇ ₹{v} ਤੋਂ ਉੱਪਰ ਹੀ ਚਾਹੀਦਾ ਹੈ (ਦੂਜੇ ਰਾਜ ਵਿੱਚ ₹50,000 ਤੋਂ ਉੱਪਰ; ਦੂਜੇ ਰਾਜ ਜਾਣ ਵਾਲੇ ਜੌਬ ਵਰਕ ਅਤੇ ਹੈਂਡੀਕ੍ਰਾਫ਼ਟ ’ਤੇ ਹਰ ਰਕਮ ’ਤੇ ਚਾਹੀਦਾ ਹੈ)।",
  "ev.fromirn": "ਜੇ ਤੁਹਾਡੇ ਬਿਜ਼ਨੈੱਸ ਨੂੰ ਈ-ਇਨਵੌਇਸ ਬਣਾਉਣਾ ਪੈਂਦਾ ਹੈ, ਤਾਂ ਇਸ ਇਨਵੌਇਸ ਦਾ ਈ-ਵੇ ਬਿੱਲ ਪੋਰਟਲ ਸਿਰਫ਼ ਇਸਦੇ IRN ਤੋਂ ਬਣਾਉਂਦਾ ਹੈ: “ਈ-ਇਨਵੌਇਸ ਦੇ ਨਾਲ ਈ-ਵੇਅ ਬਿੱਲ ਵੀ ਬਣਾਓ” ’ਤੇ ਟਿੱਕ ਕਰੋ ਅਤੇ ਈ-ਇਨਵੌਇਸ ਫ਼ਾਈਲ ਬਣਾਓ।",
  "ev.tidchk": "ਟ੍ਰਾਂਸਪੋਰਟਰ ID ਦਾ ਆਖ਼ਰੀ ਅੱਖਰ ਮੇਲ ਨਹੀਂ ਖਾਂਦਾ। ਟਾਈਪਿੰਗ ਦੀ ਗਲਤੀ ਤਾਂ ਨਹੀਂ, ਇੱਕ ਵਾਰ ਚੈੱਕ ਕਰੋ।",
  "ei.rmnote": "ਜੇ ਤੁਸੀਂ ਇਹ IRN ਪੋਰਟਲ ’ਤੇ ਕੈਂਸਲ ਕੀਤਾ ਹੈ, ਤਾਂ ਇਹ ਇਨਵੌਇਸ ਨੰਬਰ ਮੁੜ ਕਦੇ ਰਜਿਸਟਰ ਨਹੀਂ ਹੋਵੇਗਾ। ਸਹੀ ਇਨਵੌਇਸ ਨਵੇਂ ਨੰਬਰ ਨਾਲ ਬਣਾਓ।",
