  "c.cn30": "ਇਸ ਕ੍ਰੈਡਿਟ ਨੋਟ ਦੀ ਤਾਰੀਖ਼ ਉਸ ਇਨਵੌਇਸ ਦਾ ਫ਼ਾਈਨੈਂਸ਼ੀਅਲ ਈਅਰ ਖ਼ਤਮ ਹੋਣ ਤੋਂ ਬਾਅਦ ਆਉਣ ਵਾਲੀ 30 ਨਵੰਬਰ ਤੋਂ ਬਾਅਦ ਦੀ ਹੈ (ਜਾਂ ਉਸ ਸਾਲ ਦੀ ਸਾਲਾਨਾ ਰਿਟਰਨ ਭਰਨ ਤੋਂ ਬਾਅਦ ਦੀ, ਜੇ ਉਹ ਪਹਿਲਾਂ ਭਰੀ ਗਈ)। ਉਸ ਤਾਰੀਖ਼ ਤੋਂ ਬਾਅਦ ਇਸ ਉੱਤੇ GST ਘਟਾਇਆ ਨਹੀਂ ਜਾ ਸਕਦਾ (ਬਿਜ਼ਨਸ ਡਾਕੂਮੈਂਟ ਵਜੋਂ ਨੋਟ ਫਿਰ ਵੀ ਠੀਕ ਹੈ)। ਫਿਰ ਵੀ ਸੇਵ ਕਰੀਏ?",
