  "s.h.pf2": "PF: ਬੇਸਿਕ ਦਾ 12% (₹25,000 ਤੱਕ ਦੀ ਬੇਸਿਕ ’ਤੇ)। ESI: 0.75%, ਜਦੋਂ ਗ੍ਰੌਸ ₹21,000 ਜਾਂ ਘੱਟ ਹੋਵੇ। ਪ੍ਰੋਫ਼ੈਸ਼ਨਲ ਟੈਕਸ: ਉੱਪਰ ਚੁਣੇ ਰਾਜ ਮੁਤਾਬਕ। TDS: ਇਸ ਮਹੀਨੇ ਦੀ ਗ੍ਰੌਸ × 12 ਤੋਂ, FY 2026-27 ਦੀਆਂ ਸਲੈਬਾਂ ਅਤੇ ਸਟੈਂਡਰਡ ਡਿਡਕਸ਼ਨ ਨਾਲ। ਆਪਣੇ ਨਿਯਮਾਂ ਨਾਲ ਮਿਲਾ ਕੇ ਦੇਖੋ।",
