  "app.local": "ਡਾਟਾ ਹੋਮ ਨਹੀਂ ਖੁੱਲ੍ਹਿਆ, ਇਸ ਲਈ ਸਿਰਫ਼ ਇਸੇ ਸਾਈਟ ਉੱਤੇ ਇਸ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਸੇਵ ਹੈ। ਅਗਲੀ ਵਾਰ ਇਹ ਡਾਟਾ ਹੋਮ ਵਿੱਚ ਚਲਾ ਜਾਵੇਗਾ।",
  "app.vault": "ਇਸ ਬ੍ਰਾਊਜ਼ਰ ਦੇ ਡਾਟਾ ਹੋਮ ਵਿੱਚ ਸੇਵ ਹੈ, ਜੋ Nivesh Sahayak ਦੇ ਹਰ ਟੂਲ ਨਾਲ ਸਾਂਝਾ ਹੈ। ਸਾਨੂੰ ਕੁਝ ਨਹੀਂ ਭੇਜਿਆ ਜਾਂਦਾ।",
  "app.help": "ਇਹ ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ",
  "app.helpp": "billing., cash-memo. ਅਤੇ credit-note. ਉੱਤੇ ਬਣੇ ਬਿੱਲ ਇੱਥੇ ਆਪੇ ਦਿਸਦੇ ਹਨ। ਮਿਲਿਆ ਅਤੇ ਦਿੱਤਾ ਪੈਸਾ ਇੱਥੇ ਲਿਖੋ; ਐਪ ਉਸ ਨੂੰ ਬਿੱਲਾਂ ਨਾਲ ਜੋੜਦਾ ਹੈ, ਐਡਵਾਂਸ ਰੱਖਦਾ ਹੈ ਅਤੇ ਬਕਾਇਆ ਤੇ ਹੱਥ ਦਾ ਕੈਸ਼ ਕੱਢਦਾ ਹੈ।",
  "app.invfix": "ਇੱਥੇ ਚੁਕਤਾ ਹੋਏ ਇਨਵੌਇਸ ਬਿਲਿੰਗ ਸਾਈਟ ਉੱਤੇ ਵੀ ਪੇਡ ਦਿਸਣਗੇ।",
