  "g3.refill": "ਸੇਵ ਕੀਤੇ ਬਿੱਲਾਂ ਤੋਂ ਦੁਬਾਰਾ ਭਰੋ",
  "g3.save": "ਇਹ ਵਰਕਿੰਗ ਸੇਵ ਕਰੋ",
  "g3.saved": "ਵਰਕਿੰਗ ਤੁਹਾਡੇ ਡਾਟਾ ਹੋਮ ਵਿੱਚ ਸੇਵ ਹੋ ਗਈ।",
  "g3.refilled": "ਅੰਕੜੇ ਤੁਹਾਡੇ ਸੇਵ ਕੀਤੇ ਬਿੱਲਾਂ ਤੋਂ ਦੁਬਾਰਾ ਭਰ ਦਿੱਤੇ ਗਏ।",
  "g3.loaded": "{d} ਨੂੰ ਸੇਵ ਕੀਤੀ ਤੁਹਾਡੀ ਵਰਕਿੰਗ ਦਿਸ ਰਹੀ ਹੈ। ਨਵੇਂ ਸਿਰੇ ਤੋਂ ਸ਼ੁਰੂ ਕਰਨ ਲਈ “ਸੇਵ ਕੀਤੇ ਬਿੱਲਾਂ ਤੋਂ ਦੁਬਾਰਾ ਭਰੋ” ਦਬਾਓ।",
  "g3.formh": "ਤੁਹਾਡੇ ਸੇਵ ਕੀਤੇ ਬਿੱਲਾਂ ਦੇ ਅੰਕੜੇ ਭਰ ਦਿੱਤੇ ਗਏ ਹਨ। ਕਿਸੇ ਵੀ ਬਾਕਸ ਵਿੱਚ ਬਦਲਾਅ ਕਰ ਸਕਦੇ ਹੋ, ਜਿਵੇਂ ਆਪਣੇ GSTR-2B ਵਿੱਚ ਦਿਸਦੇ ITC ਅਨੁਸਾਰ। ਤੁਹਾਡੇ ਬਦਲੇ ਹੋਏ ਬਾਕਸਾਂ ’ਤੇ ਨਿਸ਼ਾਨ ਲੱਗਦਾ ਹੈ।",
  "g3.h.out": "3.1 ਆਊਟਵਰਡ ਅਤੇ ਰਿਵਰਸ ਚਾਰਜ ਸਪਲਾਈ ’ਤੇ ਟੈਕਸ",
  "g3.h.itc": "4(A) ਮਿਲਣ ਵਾਲਾ ਇਨਪੁੱਟ ਟੈਕਸ ਕ੍ਰੈਡਿਟ",
  "g3.h.rev": "4(B) ਰਿਵਰਸ ਕੀਤਾ ਇਨਪੁੱਟ ਟੈਕਸ ਕ੍ਰੈਡਿਟ",
  "g3.h.exin": "5 ਐਗਜ਼ੈਂਪਟ, ਨਿਲ ਅਤੇ ਨਾਨ-GST ਇਨਵਰਡ ਸਪਲਾਈ",
  "g3.h.more": "ਅੱਗੇ ਲਿਆਂਦਾ ਕ੍ਰੈਡਿਟ, ਵਿਆਜ ਅਤੇ ਲੇਟ ਫ਼ੀਸ",
  "g3.b.a": "(a) ਟੈਕਸੇਬਲ ਆਊਟਵਰਡ ਸਪਲਾਈ",
  "g3.b.b": "(b) ਜ਼ੀਰੋ ਰੇਟਿਡ (ਐਕਸਪੋਰਟ, SEZ)",
