  "g3.p.cf": "ਅਗਲੀ ਮਿਆਦ ਲਈ ਬਚਿਆ ਕ੍ਰੈਡਿਟ",
  "g3.note": "ਸੈੱਟ-ਆਫ਼ CGST ਐਕਟ ਦੀ ਧਾਰਾ 49 ਅਤੇ ਨਿਯਮ 88A ਮੁਤਾਬਕ: ਪਹਿਲਾਂ IGST ਕ੍ਰੈਡਿਟ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ, ਫਿਰ CGST ਅਤੇ SGST/UTGST ਕ੍ਰੈਡਿਟ; CGST ਅਤੇ SGST ਕ੍ਰੈਡਿਟ ਇੱਕ-ਦੂਜੇ ਦੇ ਵਿਰੁੱਧ ਕਦੇ ਨਹੀਂ ਵਰਤੇ ਜਾਂਦੇ; ਰਿਵਰਸ ਚਾਰਜ ਟੈਕਸ ਕੈਸ਼ ਵਿੱਚ ਹੀ ਭਰਿਆ ਜਾਂਦਾ ਹੈ। ਫ਼ਾਈਲ ਕਰਨ ਵੇਲੇ ਆਖ਼ਰੀ ਸੈੱਟ-ਆਫ਼ ਪੋਰਟਲ ਕਰਦਾ ਹੈ।",
  "g3.w.zr": "ਬਿੱਲ {no} ਐਕਸਪੋਰਟ ਜਾਂ SEZ ਬਿੱਲ ਹੈ, ਪਰ ਉਸ ਵਿੱਚ CGST/SGST ਦਿਸ ਰਿਹਾ ਹੈ। ਜ਼ੀਰੋ ਰੇਟਿਡ ਸਪਲਾਈ ’ਤੇ ਸਿਰਫ਼ IGST ਲੱਗਦਾ ਹੈ।",
  "g3.w.rcmv": "ਵਾਊਚਰ {no}: ਰਿਵਰਸ ਚਾਰਜ ਟੈਕਸ CGST + SGST ਮੰਨ ਕੇ ਲਿਆ ਗਿਆ ਹੈ। ਜੇ ਸਪਲਾਇਰ ਦੂਜੇ ਰਾਜ ਦਾ ਹੈ ਤਾਂ ਬਾਕਸ ਬਦਲ ਕੇ IGST ਕਰੋ।",
  "g3.w.nogstin": "{p} ਤੋਂ ਖ਼ਰੀਦ ਬਿੱਲ {no} ਵਿੱਚ ਸਪਲਾਇਰ ਦਾ GSTIN ਸਹੀ ਨਹੀਂ ਹੈ, ਇਸ ਲਈ ਉਸ ਦਾ ITC GSTR-2B ਵਿੱਚ ਨਹੀਂ ਦਿਸੇਗਾ।",
  "g3.w.2b": "ਬਾਕਸ 4(A)(5) ਦਾ ITC ਤੁਹਾਡੇ ਸੇਵ ਕੀਤੇ ਖ਼ਰੀਦ ਬਿੱਲਾਂ ਅਤੇ ਖ਼ਰਚਿਆਂ ਤੋਂ ਆਇਆ ਹੈ। ਸਿਰਫ਼ ਉਹੀ ਕਲੇਮ ਕਰੋ ਜੋ ਤੁਹਾਡੇ GSTR-2B ਵਿੱਚ ਦਿਸਦਾ ਹੈ; GSTR-2B ਦਾ ਅੰਕੜਾ ਘੱਟ ਹੋਵੇ ਤਾਂ ਉਹੀ ਟਾਈਪ ਕਰੋ।",
  "g3.w.neg": "ਉਪਲਬਧ ਕ੍ਰੈਡਿਟ ਜ਼ੀਰੋ ਤੋਂ ਹੇਠਾਂ ਹੈ: ਰਿਵਰਸਲ ਕ੍ਰੈਡਿਟ ਤੋਂ ਜ਼ਿਆਦਾ ਹਨ। ਫ਼ਰਕ ਕੈਸ਼ ਵਿੱਚ ਭਰਨਾ ਪਵੇਗਾ; ਆਪਣੇ ਅਕਾਊਂਟੈਂਟ ਤੋਂ ਪੁੱਛੋ।",
