  "g2.w.gstin": "ਇਹ GSTR-2B GSTIN {a} ਦੀ ਹੈ, ਪਰ ਚੁਣੇ ਹੋਏ ਬਿਜ਼ਨਸ ਦਾ GSTIN {b} ਹੈ। ਸਹੀ ਬਿਜ਼ਨਸ ਚੁਣੋ।",
