  "g2.s.only2b": "GSTR-2B ਵਿੱਚ ਹੈ, ਤੁਹਾਡੇ ਖ਼ਰੀਦ ਬਿੱਲਾਂ ਵਿੱਚ ਨਹੀਂ",
  "g2.s.onlybooks": "ਤੁਹਾਡੇ ਖ਼ਰੀਦ ਬਿੱਲਾਂ ਵਿੱਚ ਹੈ, GSTR-2B ਵਿੱਚ ਨਹੀਂ",
