  "g2.h.ok": "ਸਪਲਾਇਰ, ਨੰਬਰ, ਰਕਮ ਅਤੇ ਤਾਰੀਖ਼ ਸਭ ਇੱਕੋ ਜਿਹੇ। ਇਹ ਕ੍ਰੈਡਿਟ ਕਲੇਮ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।",
  "g2.h.diff": "ਦੋਵੇਂ ਥਾਂ ਮਿਲਿਆ, ਪਰ ਅੰਕੜੇ ਵੱਖਰੇ ਹਨ। ਸਪਲਾਇਰ ਨਾਲ ਬਿੱਲ ਜਾਂਚੋ; ਸਿਰਫ਼ ਉਹੀ ਕਲੇਮ ਕਰੋ ਜੋ GSTR-2B ਵਿੱਚ ਦਿਸਦਾ ਹੈ।",
  "g2.h.numdiff": "ਸਪਲਾਇਰ ਅਤੇ ਰਕਮ ਉਹੀ ਹਨ, ਪਰ ਬਿੱਲ ਨੰਬਰ ਵੱਖਰਾ ਲਿਖਿਆ ਹੈ। ਆਮ ਤੌਰ ’ਤੇ ਟਾਈਪਿੰਗ ਦਾ ਫ਼ਰਕ ਹੁੰਦਾ ਹੈ: ਆਪਣੀ ਐਂਟਰੀ ਠੀਕ ਕਰੋ।",
  "g2.h.only2b": "ਸਪਲਾਇਰ ਨੇ ਇਹ ਬਿੱਲ ਰਿਪੋਰਟ ਕੀਤੇ ਹਨ, ਪਰ ਤੁਹਾਡੀਆਂ ਬੁੱਕਾਂ ਵਿੱਚ ਸੇਵ ਨਹੀਂ ਹਨ। ਮਾਲ ਜਾਂ ਸਰਵਿਸ ਮਿਲੀ ਹੋਵੇ ਤਾਂ ਇਹਨਾਂ ਨੂੰ ਐਂਟਰ ਕਰੋ, ਜਾਂ ਸਪਲਾਇਰ ਤੋਂ ਠੀਕ ਕਰਵਾਓ।",
  "g2.h.onlybooks": "ਇਹਨਾਂ ਤਾਰੀਖ਼ਾਂ ਦੇ ਤੁਹਾਡੇ ਬਿੱਲ ਜੋ ਸਪਲਾਇਰ ਨੇ ਹਾਲੇ ਰਿਪੋਰਟ ਨਹੀਂ ਕੀਤੇ। GSTR-2B ਵਿੱਚ ਦਿਸਣ ਤੱਕ ITC ਕਲੇਮ ਨਾ ਕਰੋ; ਸਪਲਾਇਰ ਨੂੰ ਯਾਦ ਕਰਵਾਓ।",
  "g2.h.noitc": "ਉਹ ਬਿੱਲ ਜਿਨ੍ਹਾਂ ’ਤੇ ਪੋਰਟਲ ITC ਉਪਲਬਧ ਨਹੀਂ ਦਿਖਾਉਂਦਾ (ਜਿਵੇਂ ਪਲੇਸ ਆਫ਼ ਸਪਲਾਈ ਸਪਲਾਇਰ ਦੇ ਰਾਜ ਵਿੱਚ, ਜਾਂ ਟਾਈਮ ਲਿਮਿਟ)।",
