  "td.no.y": "ਹਾਲੇ TDS ਨਹੀਂ: ਸਾਲ ਦਾ ਕੁੱਲ {l} ਦੇ ਅੰਦਰ ਹੈ। ਜਿਸ ਪੇਮੈਂਟ ਨਾਲ ਇਹ ਲਿਮਿਟ ਪਾਰ ਹੋਵੇ, ਉਸ ’ਤੇ ਕੱਟੋ।",
  "td.no.q": "ਹਾਲੇ TDS ਨਹੀਂ: ਇਸ ਸਾਲ ਇਸ ਸੇਲਰ ਤੋਂ ਖ਼ਰੀਦ {l} ਤੋਂ ਉੱਪਰ ਨਹੀਂ ਹੈ।",
  "td.catch": "ਇਸ ਪੇਮੈਂਟ ਨਾਲ ਸਾਲ ਦਾ ਕੁੱਲ ਲਿਮਿਟ ਤੋਂ ਉੱਪਰ ਚਲਾ ਜਾਂਦਾ ਹੈ, ਇਸ ਲਈ TDS ਪੂਰੇ ਕੁੱਲ ’ਤੇ ਕੱਢਿਆ ਜਾਂਦਾ ਹੈ, ਜਿਸ ਵਿੱਚ ਪਹਿਲਾਂ ਬਿਨਾਂ TDS ਦਿੱਤੇ {y} ਵੀ ਸ਼ਾਮਲ ਹਨ। ਜੇ ਇਸ ਵਿੱਚੋਂ ਕੁਝ ’ਤੇ TDS ਪਹਿਲਾਂ ਕੱਟਿਆ ਜਾ ਚੁੱਕਾ ਹੈ ਤਾਂ ਸਿਰਫ਼ ਫ਼ਰਕ ਕੱਟੋ।",
  "td.nopan": "ਸਹੀ PAN ਨਾ ਹੋਣ ’ਤੇ ਰੇਟ 20% ਜਾਂ ਆਮ ਰੇਟ ਦਾ ਦੁੱਗਣਾ, ਜੋ ਜ਼ਿਆਦਾ ਹੋਵੇ (ਮਾਲ ਦੀ ਖ਼ਰੀਦ ’ਤੇ 5%)। ਪ੍ਰਾਪਤ ਕਰਨ ਵਾਲੇ ਤੋਂ ਉਸ ਦਾ PAN ਮੰਗੋ।",
  "td.trans": "ਜਿਸ ਟਰਾਂਸਪੋਰਟਰ ਕੋਲ 10 ਜਾਂ ਉਸ ਤੋਂ ਘੱਟ ਮਾਲ-ਗੱਡੀਆਂ ਹੋਣ ਅਤੇ ਉਹ PAN ਸਮੇਤ ਡਿਕਲੇਰੇਸ਼ਨ ਦੇਵੇ, ਉਸ ਨੂੰ ਬਿਨਾਂ TDS ਦੇ ਪੇਮੈਂਟ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।",
  "td.q": "TDS ਤਾਂ ਹੀ ਕੱਟੋ ਜੇ ਪਿਛਲੇ ਸਾਲ ਤੁਹਾਡਾ ਟਰਨਓਵਰ ₹10 ਕਰੋੜ ਤੋਂ ਉੱਪਰ ਸੀ, ਅਤੇ ਸਿਰਫ਼ ਇਸ ਸੇਲਰ ਤੋਂ ਸਾਲ ਦੀ ₹50 ਲੱਖ ਤੋਂ ਉੱਪਰ ਦੀ ਖ਼ਰੀਦ ’ਤੇ।",
  "td.ib": "ਟੈਕਸ ਆਡਿਟ ਵਿੱਚ ਨਾ ਆਉਣ ਵਾਲੇ ਇੰਡੀਵਿਜੂਅਲ ਦੇ ਦਿੱਤੇ ਕਿਰਾਏ ’ਤੇ TDS ਇੱਕੋ ਵਾਰ ਕੱਟਿਆ ਜਾਂਦਾ ਹੈ, ਸਾਲ ਜਾਂ ਕਿਰਾਏਦਾਰੀ ਦੇ ਆਖ਼ਰੀ ਮਹੀਨੇ ਦੇ ਕਿਰਾਏ ਵਿੱਚੋਂ।",
