  "b1.v_tcs10": "ਗੱਡੀ ਜਾਂ ਨੋਟੀਫਾਈਡ ਸਮਾਨ 'ਤੇ TCS ਤਾਂ ਹੀ ਲੱਗਦਾ ਹੈ ਜਦੋਂ ਇੱਕ ਆਈਟਮ ਦੀ ਕੀਮਤ ₹10 ਲੱਖ ਤੋਂ ਉੱਪਰ ਹੋਵੇ (ਨੋਟੀਫਿਕੇਸ਼ਨ 36/2025 'ਤੇ CBDT FAQ, 23 ਅਪ੍ਰੈਲ 2025)। ਇਸ ਬਿੱਲ ਦੀ ਕੋਈ ਆਈਟਮ ਅਜਿਹੀ ਨਹੀਂ। TCS ਦਾ ਟਿੱਕ ਹਟਾਓ।",
  "b1.c_tcs10g": "GST ਤੋਂ ਬਿਨਾਂ ਕੋਈ ਆਈਟਮ ₹10 ਲੱਖ ਤੋਂ ਉੱਪਰ ਨਹੀਂ, ਸਿਰਫ਼ GST ਜੋੜ ਕੇ ਉੱਪਰ ਹੈ। ਐਕਟ ਵਿੱਚ \"ਵੈਲਿਊ\" ਲਿਖਿਆ ਹੈ ਅਤੇ ਕਿਸੇ ਸਰਕੂਲਰ ਨੇ ਤੈਅ ਨਹੀਂ ਕੀਤਾ ਕਿ ਇਸ ਲਿਮਿਟ ਵਿੱਚ GST ਗਿਣਿਆ ਜਾਵੇ ਜਾਂ ਨਹੀਂ। ਕੀ ਇਸ ਬਿੱਲ 'ਤੇ TCS ਲੈਣਾ ਹੈ?",
  "b1.tcsbh": "CBDT ਸਰਕੂਲਰ 17/2020 (ਪੈਰਾ 4.6.1, ਪੁਰਾਣੇ ਸੈਕਸ਼ਨ 206C ਲਈ): TCS ਮਿਲੀ ਰਕਮ 'ਤੇ GST ਸਮੇਤ ਲਿਆ ਜਾਂਦਾ ਹੈ, GST, ਡਿਸਕਾਊਂਟ ਜਾਂ ਰਿਟਰਨ ਲਈ ਕੁਝ ਨਹੀਂ ਘਟਦਾ। ਟੈਕਸੇਬਲ ਵੈਲਿਊ ਤਾਂ ਹੀ ਚੁਣੋ ਜਦੋਂ ਤੁਹਾਡਾ CA ਕਹੇ।",
  "b1.cntcs": "ਬਿੱਲ {no} 'ਤੇ {v} TCS ਲੱਗਿਆ ਸੀ। ਇਹ ਕ੍ਰੈਡਿਟ ਨੋਟ ਉਹ TCS ਨਹੀਂ ਘਟਾਉਂਦਾ: CBDT ਸਰਕੂਲਰ 17/2020 (ਪੈਰਾ 4.6.1) ਮੁਤਾਬਕ ਸੇਲਜ਼ ਰਿਟਰਨ 'ਤੇ ਕੋਈ ਐਡਜਸਟਮੈਂਟ ਨਹੀਂ। ਖਰੀਦਦਾਰ ਇਹ TCS ਆਪਣੀ ਇਨਕਮ ਟੈਕਸ ਰਿਟਰਨ ਵਿੱਚ ਕਲੇਮ ਕਰਦਾ ਹੈ।",
  "b1.tcspan": "ਖਰੀਦਦਾਰ ਦਾ PAN",
  "b1.tcspanh": "ਖਰੀਦਦਾਰ ਦੇ GSTIN ਤੋਂ ਆਪਣੇ ਆਪ ਲਿਆ ਜਾਂਦਾ ਹੈ। ਸਹੀ PAN ਨਾ ਹੋਵੇ ਤਾਂ TCS ਉੱਚੇ ਰੇਟ 'ਤੇ ਲੱਗਦਾ ਹੈ (ਸੈਕਸ਼ਨ 397(2)) ਅਤੇ ਬਣਾਉਣ ਵਾਲਾ ਡਿਕਲੇਰੇਸ਼ਨ ਮੰਨਿਆ ਨਹੀਂ ਜਾਂਦਾ।",
  "b1.tcsnr": "ਖਰੀਦਦਾਰ ਨਾਨ-ਰੈਜ਼ੀਡੈਂਟ ਹੈ ਅਤੇ ਭਾਰਤ ਵਿੱਚ ਉਸਦਾ ਕੋਈ ਕਾਰੋਬਾਰੀ ਟਿਕਾਣਾ ਨਹੀਂ (ਬਿਨਾਂ PAN ਵਾਲਾ ਉੱਚਾ ਰੇਟ ਨਹੀਂ ਲੱਗੇਗਾ)",
  "b1.tcsnopan": "ਖਰੀਦਦਾਰ ਦਾ ਸਹੀ PAN ਨਹੀਂ: TCS {r}% (ਰੇਟ ਦਾ ਦੁੱਗਣਾ ਜਾਂ 5%, ਜੋ ਵੱਧ ਹੋਵੇ, 20% ਤੱਕ, ਸੈਕਸ਼ਨ 397(2))।",
  "b1.repeat": "ਇਹ ਬਿੱਲ ਦੁਹਰਾਓ",
  "b1.rep_no": "ਨਹੀਂ ਦੁਹਰਾਉਣਾ",
  "b1.rep_m": "ਹਰ ਮਹੀਨੇ",
  "b1.rep_q": "ਹਰ ਤਿਮਾਹੀ",
  "b1.reph": "ਆਪਣੇ ਆਪ ਕੁਝ ਨਹੀਂ ਬਣਦਾ: Nivesh Sahayak ਐਪ ਵਿੱਚ ਬਣਨ ਵਾਲੀਆਂ ਕਾਪੀਆਂ ਦੀ ਲਿਸਟ ਆਉਂਦੀ ਹੈ, ਤੁਸੀਂ ਟੈਪ ਕਰਕੇ ਬਣਾਉਂਦੇ ਹੋ।",
  "b1.repuntil": "ਕਦੋਂ ਤੱਕ ਦੁਹਰਾਓ",
  "b1.repuh": "ਹਮੇਸ਼ਾ ਦੁਹਰਾਉਣ ਲਈ ਖਾਲੀ ਛੱਡੋ।",
  "b1.rep_t": "ਦੁਹਰਾਏ ਜਾਣ ਵਾਲੇ ਬਿੱਲ",
  "b1.rep_p": "\"ਇਹ ਬਿੱਲ ਦੁਹਰਾਓ\" ਨਾਲ ਸੇਵ ਕੀਤੇ ਬਿੱਲ। ਜੋ ਕਾਪੀਆਂ ਚਾਹੀਦੀਆਂ ਹਨ ਉਹਨਾਂ 'ਤੇ ਟਿੱਕ ਕਰੋ ਅਤੇ ਬਟਨ ਦਬਾਓ; ਹਰ ਕਾਪੀ ਨੂੰ ਅਗਲਾ ਇਨਵੌਇਸ ਨੰਬਰ ਅਤੇ ਦਿਖਾਈ ਤਾਰੀਖ ਮਿਲਦੀ ਹੈ। ਤੁਹਾਡੇ ਟੈਪ ਤੋਂ ਬਿਨਾਂ ਕੁਝ ਨਹੀਂ ਬਣਦਾ।",
  "b1.rep_due": "ਬਣਾਉਣੇ ਬਾਕੀ",
  "b1.rep_line": "{d} · {no} ਦੀ ਕਾਪੀ",
  "b1.rep_make": "ਇਹ ਬਿੱਲ ਬਣਾਓ",
  "b1.rep_none": "ਹੁਣ ਕੋਈ ਦੁਹਰਾਇਆ ਜਾਣ ਵਾਲਾ ਬਿੱਲ ਬਾਕੀ ਨਹੀਂ।",
  "b1.rep_made": "{n} ਬਿੱਲ ਬਣ ਗਏ। ਇਹ ਵਿਕਰੀ ਵਿੱਚ ਹਨ।",
  "b1.rep_all": "ਸਾਰੇ ਦੁਹਰਾਏ ਜਾਣ ਵਾਲੇ ਬਿੱਲ",
  "b1.rep_from": "{d} ਦੇ {no} ਤੋਂ · {n} ਕਾਪੀਆਂ ਬਣੀਆਂ",
  "b1.rep_how": "ਬਿੱਲ ਦੁਹਰਾਉਣ ਲਈ ਉਸਨੂੰ ਇਨਵੌਇਸ ਮੇਕਰ ਵਿੱਚ ਖੋਲ੍ਹੋ ਅਤੇ \"ਇਹ ਬਿੱਲ ਦੁਹਰਾਓ\" ਵਿੱਚ \"ਹਰ ਮਹੀਨੇ\" ਜਾਂ \"ਹਰ ਤਿਮਾਹੀ\" ਚੁਣੋ।",
