  "b1.rep_see": "ਦੇਖੋ ਅਤੇ ਬਣਾਓ",
  "b1.bin": "ਰੀਸਾਈਕਲ ਬਿਨ",
  "b1.binp": "ਡਿਲੀਟ ਕੀਤੇ ਬਿਜ਼ਨਸ, ਪਾਰਟੀ, ਆਈਟਮ ਅਤੇ ਡਾਕੂਮੈਂਟ ਇੱਥੇ {n} ਦਿਨ ਰਹਿੰਦੇ ਹਨ, ਫਿਰ ਹਮੇਸ਼ਾ ਲਈ ਚਲੇ ਜਾਂਦੇ ਹਨ। ਰੀਸਟੋਰ ਕਰਨ 'ਤੇ ਪਹਿਲਾਂ ਵਾਂਗ ਵਾਪਸ ਆ ਜਾਂਦਾ ਹੈ।",
