  "b1.cdel": "{x} ਡਿਲੀਟ ਕਰੋ? ਇਹ 30 ਦਿਨ ਰੀਸਾਈਕਲ ਬਿਨ ਵਿੱਚ ਰਹੇਗਾ, ਉੱਥੋਂ ਰੀਸਟੋਰ ਕਰ ਸਕਦੇ ਹੋ।",
  "b1.binned": "ਰੀਸਾਈਕਲ ਬਿਨ ਵਿੱਚ ਚਲਾ ਗਿਆ। 30 ਦਿਨ ਤੱਕ ਰੀਸਟੋਰ ਕਰ ਸਕਦੇ ਹੋ।",
  "b1.hist": "ਬਦਲਾਅ ਦਾ ਰਿਕਾਰਡ",
  "b1.changes": "ਬਦਲਾਅ",
  "b1.changesof": "ਬਦਲਾਅ: {no}",
  "b1.nolog": "ਅਜੇ ਕੋਈ ਬਦਲਾਅ ਦਰਜ ਨਹੀਂ।",
  "b1.thisdev": "ਇਹ ਡਿਵਾਈਸ",
  "b1.logp": "ਕਿਸੇ ਵੀ Nivesh Sahayak ਸਾਈਟ 'ਤੇ ਜਦੋਂ ਵੀ ਕੋਈ ਬਿਜ਼ਨਸ, ਪਾਰਟੀ, ਆਈਟਮ ਜਾਂ ਡਾਕੂਮੈਂਟ ਜੋੜਿਆ, ਬਦਲਿਆ, ਡਿਲੀਟ ਜਾਂ ਰੀਸਟੋਰ ਹੁੰਦਾ ਹੈ, ਉਹ ਤਾਰੀਖ, ਸਮਾਂ, ਨਾਂ ਅਤੇ ਕੀ ਬਦਲਿਆ ਸਮੇਤ ਇੱਥੇ ਦਰਜ ਹੁੰਦਾ ਹੈ। ਇਹ ਐਂਟਰੀਆਂ ਬਦਲੀਆਂ ਜਾਂ ਹਟਾਈਆਂ ਨਹੀਂ ਜਾ ਸਕਦੀਆਂ।",
  "b1.logrule": "ਕੰਪਨੀਆਂ ਨੂੰ 1 ਅਪ੍ਰੈਲ 2023 ਤੋਂ ਅਜਿਹਾ ਅਕਾਊਂਟਸ ਸਾਫਟਵੇਅਰ ਵਰਤਣਾ ਹੈ ਜੋ ਇਹ ਆਡਿਟ ਟ੍ਰੇਲ ਰੱਖੇ (ਕੰਪਨੀਜ਼ (ਅਕਾਊਂਟਸ) ਰੂਲਜ਼ 2014, ਰੂਲ 3(1))। ਇਹ ਇਸੇ ਬ੍ਰਾਊਜ਼ਰ ਅਤੇ ਤੁਹਾਡੀ ਬੈਕਅੱਪ ਫਾਈਲ ਵਿੱਚ ਰਹਿੰਦਾ ਹੈ।",
  "b1.logmore": "{n} ਵਿੱਚੋਂ ਨਵੀਆਂ 300 ਦਿਖ ਰਹੀਆਂ ਹਨ। ਸਾਰੀਆਂ ਲਈ Excel ਫਾਈਲ ਡਾਊਨਲੋਡ ਕਰੋ।",
