  "b1.g_safe": "ਸੁਰੱਖਿਆ",
  "b1.who": "ਇਸ ਡਿਵਾਈਸ 'ਤੇ ਤੁਹਾਡਾ ਨਾਂ",
  "b1.h_who": "ਇਸ ਡਿਵਾਈਸ 'ਤੇ ਕੀਤੇ ਹਰ ਬਦਲਾਅ ਨਾਲ ਬਦਲਾਅ ਦੇ ਰਿਕਾਰਡ ਵਿੱਚ ਦਿਖੇਗਾ।",
  "b1.lock": "ਇਸ ਤਾਰੀਖ ਤੋਂ ਪਹਿਲਾਂ ਦੇ ਡਾਕੂਮੈਂਟ ਲਾਕ ਕਰੋ",
  "b1.h_lock": "ਇਸ ਦਿਨ ਤੋਂ ਪਹਿਲਾਂ ਦੀ ਤਾਰੀਖ ਵਾਲੇ ਡਾਕੂਮੈਂਟ ਕਿਸੇ ਵੀ ਸਾਈਟ 'ਤੇ ਜੋੜੇ, ਬਦਲੇ ਜਾਂ ਡਿਲੀਟ ਨਹੀਂ ਹੋ ਸਕਣਗੇ (ਪੇਮੈਂਟ ਮਿਲ ਗਈ ਲਗਾਉਣਾ ਚੱਲਦਾ ਰਹੇਗਾ)। GST ਰਿਟਰਨ ਭਰਨ ਜਾਂ ਵਹੀ ਬੰਦ ਕਰਨ ਤੋਂ ਬਾਅਦ ਲਗਾਓ।",
  "b1.lockc": "{d} ਤੋਂ ਪਹਿਲਾਂ ਦੀ ਤਾਰੀਖ ਵਾਲੇ ਸਾਰੇ ਡਾਕੂਮੈਂਟ ਲਾਕ ਕਰੋ? ਇਹ ਤਾਰੀਖ ਹਟਾਉਣ ਤੱਕ ਉਹ ਬਦਲੇ ਨਹੀਂ ਜਾ ਸਕਣਗੇ।",
  "b1.unlockc": "ਪੁਰਾਣੇ ਡਾਕੂਮੈਂਟ ਅਨਲਾਕ ਕਰੋ ਤਾਂ ਜੋ ਫਿਰ ਬਦਲੇ ਜਾ ਸਕਣ?",
  "b1.locked": "ਲਾਕ ਹੈ: {d} ਤੋਂ ਪਹਿਲਾਂ ਦੀ ਤਾਰੀਖ ਵਾਲੇ ਡਾਕੂਮੈਂਟ ਬਦਲੇ ਨਹੀਂ ਜਾ ਸਕਦੇ। ਪਹਿਲਾਂ ਸੈਟਿੰਗ ਅਤੇ ਸੇਵ ਡੇਟਾ › ਸੈਟਿੰਗ ਵਿੱਚ ਲਾਕ ਦੀ ਤਾਰੀਖ ਹਟਾਓ।",
