  "b1.pin_p": "PIN ਲਗਾਉਣ 'ਤੇ ਤੁਹਾਡਾ ਡੇਟਾ ਇਸ ਸਕ੍ਰੀਨ ਅਤੇ Nivesh Sahayak ਐਪ ਵਿੱਚ PIN ਪਾਉਣ ਤੱਕ ਲੁਕਿਆ ਰਹਿੰਦਾ ਹੈ। ਇਹ ਸਕ੍ਰੀਨ ਲਾਕ ਹੈ, ਐਨਕ੍ਰਿਪਸ਼ਨ ਨਹੀਂ: ਡੇਟਾ ਆਪ ਨਹੀਂ ਬਦਲਦਾ, ਅਤੇ ਡਾਕੂਮੈਂਟ ਸਾਈਟਾਂ ਬਿੱਲ ਭਰਨ ਲਈ ਉਸਨੂੰ ਪੜ੍ਹ ਸਕਦੀਆਂ ਹਨ। PIN ਭੁੱਲ ਗਏ ਤਾਂ ਵਾਪਸ ਆਉਣ ਦਾ ਇੱਕੋ ਰਸਤਾ: ਇਸ ਬ੍ਰਾਊਜ਼ਰ ਦਾ ਡੇਟਾ ਮਿਟਾਓ ਅਤੇ ਬੈਕਅੱਪ ਫਾਈਲ ਰੀਸਟੋਰ ਕਰੋ।",
