  "b2.sales": "ਵਿਕਿਆ",
  "b2.dep": "ਡੈਪ੍ਰੀਸੀਏਸ਼ਨ",
  "b2.closewdv": "ਕਲੋਜ਼ਿੰਗ WDV",
  "b2.gain": "ਨਫ਼ਾ {a}: ਅਕਾਊਂਟੈਂਟ ਤੋਂ ਪੁੱਛੋ",
  "b2.farules": "ਡੈਪ੍ਰੀਸੀਏਸ਼ਨ ਕਿਵੇਂ ਕੱਢਿਆ ਜਾਂਦਾ ਹੈ",
  "b2.farule1": "ਖਾਤਿਆਂ ਦਾ ਡੈਪ੍ਰੀਸੀਏਸ਼ਨ ਕੰਪਨੀਜ਼ ਐਕਟ, 2013 ਦੇ ਸ਼ਡਿਊਲ II ਮੁਤਾਬਕ ਹੈ: ਹਰ ਤਰ੍ਹਾਂ ਦੇ ਐਸੇਟ ਦੀ ਵਰਤੋਂ ਦੀ ਉਮਰ ਹੈ (ਜਿਵੇਂ ਕੰਪਿਊਟਰ 3 ਸਾਲ, ਫਰਨੀਚਰ 10 ਸਾਲ, ਪਲਾਂਟ ਅਤੇ ਮਸ਼ੀਨਰੀ 15 ਸਾਲ, ਕਾਰ 8 ਸਾਲ), ਬਚੀ ਵੈਲਿਊ ਆਮ ਤੌਰ ਤੇ ਲਾਗਤ ਦੇ 5% ਤੋਂ ਵੱਧ ਨਹੀਂ ਹੁੰਦੀ, ਅਤੇ ਸਾਲ ਦੇ ਵਿੱਚ ਜੋੜੇ ਜਾਂ ਵੇਚੇ ਐਸੇਟ ਉੱਤੇ ਸਿਰਫ਼ ਵਰਤੋਂ ਵਾਲੇ ਦਿਨਾਂ ਦਾ ਡੈਪ੍ਰੀਸੀਏਸ਼ਨ ਲੱਗਦਾ ਹੈ। ਸਟ੍ਰੇਟ ਲਾਈਨ (SLM: ਹਰ ਸਾਲ ਬਰਾਬਰ ਰਕਮ) ਜਾਂ ਰਿਟਨ ਡਾਊਨ ਵੈਲਿਊ (WDV: ਬਚੀ ਰਕਮ ਉੱਤੇ ਤੈਅ ਰੇਟ) ਚੁਣੋ। ਪ੍ਰੋਪਰਾਈਟਰ ਅਤੇ ਫਰਮਾਂ ਅਕਸਰ ਇਹੀ ਤਰੀਕਾ ਵਰਤਦੀਆਂ ਹਨ; ਫ਼ੈਸਲਾ ਤੁਹਾਡਾ ਅਕਾਊਂਟੈਂਟ ਕਰਦਾ ਹੈ।",
  "b2.farule2": "ਇਨਕਮ ਟੈਕਸ ਡੈਪ੍ਰੀਸੀਏਸ਼ਨ ਹਰ ਬਲਾਕ ਦਾ ਵੱਖਰਾ ਨਿਕਲਦਾ ਹੈ: ਬਲਾਕ ਰੇਟ ਉੱਤੇ ਰਿਟਨ ਡਾਊਨ ਵੈਲਿਊ (ਜਿਵੇਂ ਪਲਾਂਟ ਅਤੇ ਮਸ਼ੀਨਰੀ 15%, ਫਰਨੀਚਰ 10%, ਕੰਪਿਊਟਰ 40%), ਸਾਲ ਵਿੱਚ 180 ਦਿਨ ਤੋਂ ਘੱਟ ਵਰਤੇ ਐਸੇਟ ਉੱਤੇ ਅੱਧਾ ਰੇਟ, ਅਤੇ ਵਿਕਰੀ ਦਾ ਪੈਸਾ ਬਲਾਕ ਵਿੱਚੋਂ ਘਟਦਾ ਹੈ। ਇਹ ਸਿਰਫ਼ ਇਨਕਮ ਟੈਕਸ ਰਿਟਰਨ ਲਈ ਹੈ, ਖਾਤਿਆਂ ਵਿੱਚ ਕਦੇ ਨਹੀਂ ਪਾਇਆ ਜਾਂਦਾ। ਭਰੇ ਰੇਟ ਆਮ ਬਲਾਕ ਰੇਟ ਹਨ: ਆਪਣੇ ਅਕਾਊਂਟੈਂਟ ਤੋਂ ਪੱਕਾ ਕਰੋ, ਖਾਸ ਕਰਕੇ 1 ਅਪ੍ਰੈਲ 2026 ਤੋਂ ਇਨਕਮ-ਟੈਕਸ ਐਕਟ, 2025 ਵਾਲੇ ਸਾਲਾਂ ਲਈ।",
  "b2.farule3": "ਡੈਪ੍ਰੀਸੀਏਸ਼ਨ ਤੁਹਾਡੇ ਖਾਤਿਆਂ ਵਿੱਚ ਤਦ ਹੀ ਜਾਂਦਾ ਹੈ ਜਦੋਂ ਤੁਸੀਂ 'ਡੈਪ੍ਰੀਸੀਏਸ਼ਨ ਪਾਓ' ਦੱਬਦੇ ਹੋ: ਸਾਲ ਦੇ ਆਖ਼ਰੀ ਦਿਨ (ਜਾਂ ਸਾਲ ਦੇ ਵਿੱਚ ਅੱਜ) ਦੀ ਜਰਨਲ ਐਂਟਰੀ ਡੈਪ੍ਰੀਸੀਏਸ਼ਨ ਨੂੰ ਡੈਬਿਟ ਕਰਦੀ ਹੈ ਅਤੇ ਹਰ ਐਸੇਟ ਘਟਾਉਂਦੀ ਹੈ। ਬਾਅਦ ਵਿੱਚ ਐਸੇਟ ਬਦਲੋ ਤਾਂ ਦੁਬਾਰਾ ਪਾਓ, ਸਿਰਫ਼ ਫ਼ਰਕ ਜੁੜੇਗਾ।",
