  "b2.nextyear": "FY {fy} ਵਿੱਚ",
  "b2.carryh": "ਇਸ ਡਾਟਾ ਹੋਮ ਵਿੱਚ ਕੁਝ ਵੀ ਲਿਜਾਣ ਦੀ ਲੋੜ ਨਹੀਂ: ਪਾਰਟੀ ਬੈਲੇਂਸ, ਕੈਸ਼, ਬੈਂਕ ਅਤੇ ਸਟਾਕ ਆਪਣੇ ਆਪ ਨਵੇਂ ਸਾਲ ਵਿੱਚ ਚੱਲਦੇ ਰਹਿੰਦੇ ਹਨ, ਕਿਉਂਕਿ ਐਪ ਹਰ ਸੇਵ ਰਿਕਾਰਡ ਤੋਂ ਹਿਸਾਬ ਕੱਢਦਾ ਹੈ।",
  "b2.numh": "ਹਰ ਫਾਈਨੈਂਸ਼ੀਅਲ ਈਅਰ ਵਿੱਚ ਡਾਕੂਮੈਂਟ ਨੰਬਰ ਫਿਰ 001 ਤੋਂ ਸ਼ੁਰੂ ਹੁੰਦੇ ਹਨ (ਜਿਵੇਂ INV/27-28/001), ਉਹੀ ਪ੍ਰੀਫਿਕਸ ਨਾਲ, ਇਸ ਲਈ ਨਵੇਂ ਸਾਲ ਲਈ ਕੁਝ ਨਹੀਂ ਬਦਲਣਾ ਪੈਂਦਾ।",
  "b2.closet": "ਸਾਲ ਬੰਦ ਕਰੋ",
  "b2.closeh": "ਸਾਲ ਬੰਦ ਕਰਨ ਨਾਲ ਉਹ ਸਿਰਫ਼ ਪੜ੍ਹਨ ਲਈ ਰਹਿ ਜਾਂਦਾ ਹੈ: ਐਪ ਅਤੇ ਹਰ ਡਾਕੂਮੈਂਟ ਮੇਕਰ ਉਸ ਦੀ ਤਾਰੀਖ ਵਾਲੀ ਕੋਈ ਚੀਜ਼ ਸੇਵ, ਬਦਲਣ ਜਾਂ ਡਿਲੀਟ ਨਹੀਂ ਕਰਨ ਦਿੰਦੇ। ਤੁਸੀਂ ਇਸਨੂੰ ਇੱਥੇ ਕਦੇ ਵੀ ਦੁਬਾਰਾ ਖੋਲ੍ਹ ਸਕਦੇ ਹੋ।",
  "b2.reopenh": "ਇਹ ਸਾਲ ਬੰਦ ਹੈ: ਇਸ ਦੀ ਤਾਰੀਖ ਵਾਲੀ ਕੋਈ ਚੀਜ਼ ਸੇਵ, ਬਦਲੀ ਜਾਂ ਡਿਲੀਟ ਨਹੀਂ ਹੋ ਸਕਦੀ।",
  "b2.close": "FY {fy} ਬੰਦ ਕਰੋ",
