  "b2.closeq": "FY {fy} ਬੰਦ ਕਰਨਾ ਹੈ? ਦੁਬਾਰਾ ਖੋਲ੍ਹਣ ਤੱਕ ਇਸ ਦੀ ਤਾਰੀਖ ਵਾਲੀ ਕੋਈ ਚੀਜ਼ ਨਹੀਂ ਬਦਲੇਗੀ।",
