  "b2.newfile": "ਨਵਾਂ ਸਾਲ ਨਵੀਂ ਡਾਟਾ ਫਾਈਲ ਵਿੱਚ ਸ਼ੁਰੂ ਕਰੋ",
  "b2.newfileh": "ਨਵੇਂ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਜਾ ਰਹੇ ਹੋ ਜਾਂ ਨਵੇਂ ਸਿਰੇ ਤੋਂ ਸ਼ੁਰੂ ਕਰ ਰਹੇ ਹੋ? ਇਸ ਫਾਈਲ ਵਿੱਚ ਤੁਹਾਡਾ ਬਿਜ਼ਨਸ, ਗਾਹਕ, ਸਪਲਾਇਰ ਅਤੇ ਆਈਟਮਾਂ, ਅਤੇ 1 ਅਪ੍ਰੈਲ ਦੇ ਓਪਨਿੰਗ ਬੈਲੇਂਸ ਹਨ: ਹਰ ਪਾਰਟੀ ਦਾ ਬੈਲੇਂਸ, ਕੈਸ਼, ਬੈਂਕ, ਐਵਰੇਜ ਕਾਸਟ ਉੱਤੇ ਸਟਾਕ, ਅਤੇ ਫਿਕਸਡ ਐਸੇਟ, ਲੋਨ, GST, TDS ਅਤੇ ਪੂੰਜੀ ਲਈ ਇੱਕ ਜਰਨਲ ਐਂਟਰੀ (ਸਾਲ ਦਾ ਪ੍ਰੌਫਿਟ ਪੂੰਜੀ ਵਿੱਚ ਹੈ)। ਉੱਥੇ My data, ਬੈਕਅੱਪ ਵਿੱਚ ਇਸਨੂੰ ਰੀਸਟੋਰ ਕਰੋ।",
