  "b3.gd.st.meta": "ਸੈਟਿੰਗ",
  "hp.btn": "ਮਦਦ: {what}",
  "hp.biz": "ਤੁਹਾਡੇ ਬਿਜ਼ਨਸ ਦੀ ਡਿਟੇਲ, ਜੋ ਉੱਪਰ ਪ੍ਰਿੰਟ ਹੁੰਦੀ ਹੈ। ਸੁਝਾਅ ਵਿੱਚੋਂ ਸੇਵ ਕੀਤਾ ਬਿਜ਼ਨਸ ਚੁਣੋ, ਜਾਂ ਇੱਕ ਵਾਰ ਲਿਖੋ, ਅਗਲੀ ਵਾਰ ਲਈ ਸੇਵ ਹੋ ਜਾਵੇਗਾ।",
  "hp.details": "ਨੰਬਰ ਅਤੇ ਤਾਰੀਖ਼। ਹਰ ਫ਼ਾਈਨੈਂਸ਼ੀਅਲ ਸਾਲ ਵਿੱਚ ਨੰਬਰ ਆਪਣੇ ਆਪ ਵਧਦਾ ਹੈ; ਆਪਣੀ ਸੀਰੀਜ਼ ਚਲਾਉਂਦੇ ਹੋ ਤਾਂ ਬਦਲ ਸਕਦੇ ਹੋ।",
  "hp.billto": "ਜਿਸਨੂੰ ਬਿੱਲ ਦੇ ਰਹੇ ਹੋ। ਨਾਮ ਲਿਖਣਾ ਸ਼ੁਰੂ ਕਰੋ ਅਤੇ ਸੇਵ ਕੀਤਾ ਕਸਟਮਰ ਚੁਣੋ, ਜਾਂ ਨਵਾਂ ਲਿਖੋ। GSTIN ਨਾਲ ਸਟੇਟ ਭਰ ਜਾਂਦਾ ਹੈ; ਸਟੇਟ ਤੋਂ ਤੈਅ ਹੁੰਦਾ ਹੈ CGST+SGST ਜਾਂ IGST।",
  "hp.vendor": "ਜਿਸ ਸਪਲਾਇਰ ਤੋਂ ਆਰਡਰ ਕਰ ਰਹੇ ਹੋ। ਸੇਵ ਕੀਤਾ ਸਪਲਾਇਰ ਚੁਣੋ ਜਾਂ ਨਵਾਂ ਲਿਖੋ।",
  "hp.supplier": "ਬਿਨਾਂ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਵਾਲਾ ਜਿਸ ਤੋਂ ਖ਼ਰੀਦਿਆ। ਇਸ ਸੈਲਫ਼ ਇਨਵੌਇਸ 'ਤੇ GST ਰਿਵਰਸ ਚਾਰਜ ਵਿੱਚ ਤੁਸੀਂ ਖ਼ੁਦ ਭਰਦੇ ਹੋ।",
  "hp.consignee": "ਤਾਂ ਹੀ ਭਰੋ ਜੇ ਮਾਲ ਖ਼ਰੀਦਦਾਰ ਤੋਂ ਵੱਖਰੀ ਥਾਂ ਜਾਂ ਬੰਦੇ ਕੋਲ ਜਾ ਰਿਹਾ ਹੋਵੇ।",
  "hp.items": "ਹਰ ਆਈਟਮ ਜਾਂ ਸਰਵਿਸ ਦੀ ਇੱਕ ਲਾਈਨ। ਸੇਵ ਕੀਤੀ ਆਈਟਮ ਚੁਣੋ ਤਾਂ ਰੇਟ, HSN ਅਤੇ GST ਭਰ ਜਾਂਦੇ ਹਨ, ਜਾਂ ਨਵੀਂ ਲਿਖੋ। ਮਾਤਰਾ × ਰੇਟ ਵਿੱਚੋਂ ਡਿਸਕਾਊਂਟ ਘਟਾ ਕੇ ਟੈਕਸੇਬਲ ਵੈਲਿਊ ਬਣਦੀ ਹੈ।",
  "hp.notes": "ਸ਼ਰਤਾਂ, ਬੈਂਕ ਡਿਟੇਲ ਅਤੇ ਪ੍ਰਿੰਟ ਪੇਜ ਦਾ ਰੂਪ। ਅਗਲੀ ਵਾਰ ਲਈ ਡਿਫ਼ਾਲਟ ਬਣ ਕੇ ਸੇਵ ਹੁੰਦਾ ਹੈ।",
  "hp.einv": "ਜਿਨ੍ਹਾਂ ਬਿਜ਼ਨਸਾਂ ਲਈ ਈ-ਇਨਵੌਇਸ ਜਾਂ ਈ-ਵੇ ਬਿੱਲ ਬਣਾਉਣਾ ਜ਼ਰੂਰੀ ਹੈ: ਫ਼ਾਈਲ ਡਾਊਨਲੋਡ ਕਰੋ, ਸਰਕਾਰੀ ਪੋਰਟਲ 'ਤੇ ਆਪਣੇ ਲਾਗਇਨ ਨਾਲ ਅਪਲੋਡ ਕਰੋ, ਫਿਰ ਜਵਾਬ ਇੱਥੇ ਲੋਡ ਕਰੋ।",
  "hp.exp": "ਐਕਸਪੋਰਟ ਲਈ: ਸ਼ਿਪਿੰਗ ਬਿੱਲ, ਪੋਰਟ ਅਤੇ ਕਰੰਸੀ। ਐਕਸਪੋਰਟ ਜ਼ੀਰੋ-ਰੇਟਡ ਹੈ: LUT ਹੋਵੇ ਤਾਂ GST ਨਹੀਂ ਲੱਗਦਾ; ਨਾ ਹੋਵੇ ਤਾਂ IGST ਭਰ ਕੇ ਰਿਫ਼ੰਡ ਮਿਲਦਾ ਹੈ।",
  "hp.s.from": "ਜਿਸਨੇ ਤੁਹਾਨੂੰ ਪੈਸੇ ਦਿੱਤੇ। ਸੇਵ ਕੀਤਾ ਕਸਟਮਰ ਚੁਣੋ ਜਾਂ ਨਾਮ ਲਿਖੋ।",
  "hp.s.pay": "ਰਕਮ, ਤਾਰੀਖ਼ ਅਤੇ ਕਿਵੇਂ ਦਿੱਤਾ। ਕਾਨੂੰਨੀ ਹੱਦ ਤੋਂ ਵੱਧ ਕੈਸ਼ 'ਤੇ ਚੇਤਾਵਨੀ ਆਉਂਦੀ ਹੈ।",
  "hp.s.to": "ਜਿਸਨੂੰ ਤੁਸੀਂ ਪੈਸੇ ਦਿੱਤੇ। ਸੇਵ ਕੀਤਾ ਸਪਲਾਇਰ ਚੁਣੋ ਜਾਂ ਨਾਮ ਲਿਖੋ।",
  "hp.s.lines": "ਪੈਸਾ ਕਿਸ ਚੀਜ਼ ਦਾ ਸੀ, ਹਰ ਇੱਕ ਦੀ ਇੱਕ ਲਾਈਨ (ਜਿਵੇਂ ਕਿਰਾਇਆ, ਰਿਪੇਅਰ, ਭਾੜਾ)।",
  "hp.s.tdsrcm": "ਭਰੋ ਜੇ ਇਸ ਪੇਮੈਂਟ ਵਿੱਚੋਂ TDS ਕੱਟਿਆ, ਜਾਂ ਰਿਵਰਸ ਚਾਰਜ ਵਿੱਚ GST ਤੁਸੀਂ ਭਰਨਾ ਹੈ।",
  "hp.s.sign": "ਦੇਣ ਵਾਲੇ, ਲੈਣ ਵਾਲੇ ਅਤੇ ਪਾਸ ਕਰਨ ਵਾਲੇ ਦੇ ਨਾਮ। ਹੱਥ ਨਾਲ ਸਾਈਨ ਕਰਨਾ ਹੈ ਤਾਂ ਖ਼ਾਲੀ ਛੱਡੋ।",
